def squash(s: str) -> str:
    n = len(s)
    if n == 0:
        return ""
    out: list[str] = []
    i = 0
    while i < n:
        c = s[i]
        j = i + 1
        while j < n and s[j] == c:
            j += 1
        run_len = j - i
        escaped = "\\" + c if ("0" <= c <= "9" or c == "\\") else c
        if run_len >= 3:
            out.append(f"{run_len}{escaped}")
        else:
            out.append(escaped * run_len)
        i = j
    return "".join(out)
